    class _FakeTemplar:
        def __init__(self, variables):
            self.available_variables = variables
            self._variables = variables

        def template(self, value):
            if isinstance(value, string_types):
                result = value
                for k, v in self._variables.items():
                    result = result.replace('{{ %s }}' % k, str(v)).replace('{{%s}}' % k, str(v))
                return result
            return value

    templar = _FakeTemplar({'name': 'world', 'num': 42, 'vars': {'a': 1}})
    globals_dict = {'range': range}

    j2vars = AnsibleJ2Vars(templar, globals_dict)

    # undefined variable raises KeyError
    try:
        j2vars['does_not_exist']
    except KeyError as e:
        assert 'does_not_exist' in to_native(e)
    else:
        raise AssertionError("expected KeyError for undefined variable")

    # local scope wins
    local_vars = AnsibleJ2Vars(templar, globals_dict, locals={'_local_x': 'local_value'})
    assert local_vars['_local_x'] == 'local_value'

    # globals are returned as-is
    assert j2vars['range'] is range

    # plain variable is templated via the templar
    assert j2vars['name'] == 'world'
    assert j2vars['num'] == 42

    # the special 'vars' dict is returned as-is, without templating
    assert j2vars['vars'] == {'a': 1}
